import React, {useContext} from 'react'
import AuthContext from '../components/AuthContext'

function PostScreen() {
  let {user} =useContext(AuthContext)
  return (
    <h1>
      PostScreen {user && user.username}
    </h1>
  )
}

export default PostScreen
